import{_ as i,o as a,c as n,ag as t}from"./chunks/framework.PVHj0As1.js";const g=JSON.parse('{"title":"15-元组类型","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/15-元祖类型/15-元祖类型.md","filePath":"仓颉入门到实战/15-元祖类型/15-元祖类型.md","lastUpdated":1734741109000,"__rawMarkdown":"# 15-元组类型\\n\\n元组（Tuple）`/ˈtjʊpəl; ˈtʌpəl/`功能类似数组，都是管理一组数据，也是通过下标来获取元祖中的元素，但是也存在区别：\\n\\n1. 元祖可以存放不同类型的数据\\n2. 元祖指定了数据类型和元素个数后不可更改\\n\\n\\n\\n## 基本用法\\n\\n```javascript\\n    let tuple = (0, \\"abc\\", true) // 指定了元素的个数和类型\\n    println(tuple[0]) // 0\\n    println(tuple[1]) // \\"abc\\"\\n    println(tuple[2]) // true\\n```\\n\\n不可修改\\n\\n```javascript\\ntuple[0] = 100 // error: \'tuple element\' can not be assigned\\n```\\n\\n也可以指定类型并且赋值\\n\\n```javascript\\nlet x: (Int64, Float64) = (3, 3.141592)\\nlet y: (Int64, Float64, String) = (3, 3.141592, \\"PI\\")\\n```\\n\\n## 元组解构\\n\\n元祖支持通过解构来快速获取里面的内容。\\n\\n**没有使用解构**\\n\\n```javascript\\n    let tuple = (0, \\"abc\\", true)\\n    let a = tuple[0] // 0 \\n    let b = tuple[1] // \\"abc\\"\\n    let c = tuple[2] // true \\n```\\n\\n**使用了解构**\\n\\n```javascript\\n    let tuple = (0, \\"abc\\", true)\\n    let (a, b, c) = tuple  // a = 0 ,  b = \\"abc\\" , c = true\\n```\\n\\n如果我们只是想要元组中的某些值，忽略另外一些值时，可以使用 `_`  来占位。\\n\\n```javascript\\n    let tuple = (0, \\"abc\\", true)\\n    let (a, _, c) = tuple\\n    println(a) // 0 \\n    println(c) // true \\n    println(b) // error: undeclared identifier \'b\' \\n```\\n\\n\\n\\n"}'),l={name:"仓颉入门到实战/15-元祖类型/15-元祖类型.md"};function p(h,s,e,k,r,d){return a(),n("div",null,[...s[0]||(s[0]=[t("",17)])])}const c=i(l,[["render",p]]);export{g as __pageData,c as default};
